import fs from "node:fs";
import path from "node:path";

import { SAMPLES, expect, test, uniqueName } from "../../fixtures";

const KINDS = ["w9", "insurance_certificate", "contract"] as const;
type Kind = (typeof KINDS)[number];

const MIME: Record<string, string> = {
  ".pdf": "application/pdf",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".txt": "text/plain",
};

function sampleFor(kind: Kind): { name: string; mimeType: string; buffer: Buffer } {
  const needle = kind === "insurance_certificate" ? "insurance" : kind;
  let files: string[] = [];
  try {
    files = fs.readdirSync(SAMPLES);
  } catch {
    files = [];
  }
  const match = files.find((f) => f.toLowerCase().includes(needle));
  if (match) {
    const ext = path.extname(match).toLowerCase();
    return {
      name: match,
      mimeType: MIME[ext] ?? "application/octet-stream",
      buffer: fs.readFileSync(path.join(SAMPLES, match)),
    };
  }
  return {
    name: `${kind}.pdf`,
    mimeType: "application/pdf",
    buffer: Buffer.from(`%PDF-1.4\n% ${kind} sample document\n%%EOF\n`),
  };
}

test(
  "approving every extraction approves the vendor",
  { tag: "@REV-05" },
  async ({ apiAs }) => {
    test.setTimeout(120_000);
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");

    // Arrange: a vendor with three extracted documents, submitted for review.
    const createRes = await member.post("/api/vendors", {
      data: {
        name: uniqueName("REV-05 Vendor"),
        category: "software",
        contact_email: "rev05@example.test",
      },
    });
    expect(createRes.status()).toBe(201);
    const vendor = await createRes.json();
    const vendorId: string = vendor.id;

    const documentIds: string[] = [];
    for (const kind of KINDS) {
      const uploadRes = await member.post(`/api/vendors/${vendorId}/documents`, {
        multipart: { kind, file: sampleFor(kind) },
      });
      expect(uploadRes.status(), `upload ${kind}`).toBe(201);
      documentIds.push((await uploadRes.json()).id);
    }

    for (const docId of documentIds) {
      await expect
        .poll(
          async () => {
            const res = await member.get(`/api/documents/${docId}`);
            return res.ok() ? (await res.json()).status : `http ${res.status()}`;
          },
          { timeout: 60_000, intervals: [250, 500, 1000] },
        )
        .toBe("extracted");
    }

    const submitRes = await member.post(`/api/vendors/${vendorId}/submit`);
    expect(submitRes.status()).toBe(200);
    expect((await submitRes.json()).status).toBe("in_review");

    const extractionIds: string[] = [];
    for (const docId of documentIds) {
      const res = await reviewer.get(`/api/documents/${docId}/extraction`);
      expect(res.status()).toBe(200);
      const extraction = await res.json();
      expect(extraction.status).toBe("pending_review");
      extractionIds.push(extraction.id);
    }
    expect(extractionIds).toHaveLength(3);

    // Act: approve all three extractions.
    for (const extractionId of extractionIds) {
      const res = await reviewer.post(`/api/extractions/${extractionId}/decision`, {
        data: { decision: "approve" },
      });
      expect(res.status()).toBe(200);
      expect((await res.json()).status).toBe("approved");
    }

    // Assert: vendor approved.
    const vendorRes = await reviewer.get(`/api/vendors/${vendorId}`);
    expect(vendorRes.status()).toBe(200);
    expect((await vendorRes.json()).status).toBe("approved");

    // Assert: audit event recorded.
    const auditRes = await reviewer.get(`/api/vendors/${vendorId}/audit`);
    expect(auditRes.status()).toBe(200);
    const audit = await auditRes.json();
    const actions = (audit.items as Array<{ action: string }>).map((e) => e.action);
    expect(actions).toContain("vendor.approved");
  },
);
